} from 'three/webgpu';
import { 
  texture, uv, mix, vec2, vec3, vec4, dot, fract, sin, float 
} from 'three/tsl';
import { gsap } from 'gsap';
import { createText } from '@/text';

export default function createNode(config, ctx) {
  const group = new Group();
  group.name = 'home-subhead';

  // Configuration extraction
  const position = config.scenePosition ?? config.position ?? [0, 1.85, 0];
  const rotation = config.sceneRotation ?? config.rotation ?? [0, 0, 0];
  const scale = config.sceneScale ?? config.scale ?? [1, 1, 1];
  const imageUrl = config.imageUrl ?? '/prism-mock/home/nodes/cta-hero-isolated.png';
  const textContent = config.textContent ?? 'Atelier Noir — precise · luxury · technical';

  const colors = config.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  // Atlas region
  const sourceRect = config.atlasRect ?? config.sourceRect ?? { x: 0, y: 0, w: 512, h: 320 };
  const aspect = sourceRect.w / sourceRect.h;

  // Load image texture (cached, synchronous)
  const imageTexture = ctx.textureLoader(imageUrl);

  // Plane dimensions based on aspect ratio
  const planeWidth = 4.0;
  const planeHeight = planeWidth / aspect;

  // Create plane geometry
  const geometry = new PlaneGeometry(planeWidth, planeHeight, 1, 1);

  // Create material with TSL nodes for gradient + grain
  const material = new MeshBasicNodeMaterial({
    transparent: true,
    side: DoubleSide,
    depthWrite: false
  });

  // Sample image texture
  const texSample = texture(imageTexture, uv());

  // Engineered gradient overlay (surface to ink)
  const surfaceCol = vec3(0.043, 0.043, 0.063); // #0b0b10
  const inkCol = vec3(0.086, 0.086, 0.114); // #16161d
  const gradFactor = uv().y.oneMinus(); // top to bottom
  const gradient = mix(surfaceCol, inkCol, gradFactor);

  // Subtle film grain
  const grainCoord = uv().mul(float(400.0));
  const grainHash = fract(sin(dot(grainCoord, vec2(12.9898, 78.233))).mul(float(43758.5453)));
  const grainAmount = grainHash.sub(float(0.5)).mul(float(0.035));

  // Combine: blend gradient over texture, add grain
  const texRgb = texSample.rgb;
  const blended = mix(texRgb, gradient, float(0.12));
  const finalRgb = blended.add(vec3(grainAmount, grainAmount, grainAmount));

  material.colorNode = vec4(finalRgb, texSample.a);

  const plane = new Mesh(geometry, material);
  group.add(plane);

  // Render text content via ctx.fontAtlas
  let textMesh = null;
  if (textContent && ctx.fontAtlas) {
    const atlasData = ctx.fontAtlas[0] ?? ctx.fontAtlas;
    textMesh = createText(atlasData, textContent, {
      font: 'lora',
      weight: 400,
      size: 0.2,
      color: new Color(colors.paper),
      align: 'center',
      letterSpacing: 0.015,
      lineHeight: 1.0
    });
    if (textMesh) {
      textMesh.position.set(0, 0, 0.02);
      textMesh.name = 'subhead-text';
      group.add(textMesh);
    }
  }

  // Apply scene placement
  group.position.set(position[0], position[1], position[2]);
  group.rotation.set(rotation[0], rotation[1], rotation[2]);
  group.scale.set(scale[0], scale[1], scale[2]);

  // No interactions — empty handlers
  group.userData.handlers = {};

  // Cleanup
  const cleanups = [];
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (textMesh && textMesh.userData && textMesh.userData.cleanup) {
      textMesh.userData.cleanup();
    }
    gsap.killTweensOf(group);
    gsap.killTweensOf(plane);
    if (textMesh) gsap.killTweensOf(textMesh);
  };

  return group;
}
